let mwAdminBusy=false,mwAdminPreview=null;const mwRosters={};
function mwProfileStanding(d){const s=d.adminStatus;if(!s){const role={MW0001:'Secretary',MW0005:'President',MW0007:'Treasurer',MW0031:'Deputy President',MW0324:'Deputy Treasurer',MW0369:'Deputy Secretary'}[d.memberId],board=['MW0002','MW0058','MW0369','MW0003','MW0004','MW0006','MW0031','MW0258','MW0001','MW0007','MW0005','MW0246','MW0324'].includes(d.memberId);return '<div class="mw-role-badges">'+(role?'<span>'+fpEscape(role)+'</span>':'')+(board?'<span>Board member</span>':'')+'</div><div class="mw-standing"><strong>Registration: '+fpEscape(d.registrationSummary?.regStatus||'Not loaded')+'</strong><p>Benefit eligibility requires the fund and declaration checks.</p></div>';}return '<div class="mw-role-badges">'+s.roles.map(r=>'<span>'+fpEscape(r.body)+' · '+fpEscape(r.position)+'</span>').join('')+'</div><div class="mw-standing '+(s.overdueFunds||s.standing!=='CURRENT'?'mw-standing-alert':'')+'"><strong>'+fpEscape(s.displayStatus)+'</strong><p>'+s.overdueFunds+' overdue fund(s) · '+s.ongoingUnpaidFunds+' ongoing fund(s) awaiting payment</p><p>Benefits: '+fpEscape(s.benefits)+'</p><small>Registration: '+fpMoney(s.registrationPaid)+' / '+fpMoney(s.registrationRequired)+'</small></div>';}
async function mwFundRoster(code,target){const el=document.getElementById(target);if(!el)return;el.textContent='Reading this fund’s paid and unpaid members…';ftBusy=true;try{const d=await fpCall('fp_review_fund',{fundCode:code});if(!document.getElementById(target))return;if(target==='fp-fund-roster'&&document.getElementById('fp-fund').value!==code)return;mwRosters[target]={data:d,filter:'ALL'};mwRenderRoster(target);}catch(e){el.textContent='Fund member list: '+e.message;}finally{ftBusy=false;}}
function mwOn(fn,...args){return fpEscape(fn+'('+args.map(x=>JSON.stringify(x)).join(',')+')');}
function mwRenderRoster(target){
 const item=mwRosters[target],el=document.getElementById(target);if(!item||!el)return;const d=item.data,s=mwRosterStats(d.members),rows=mwRosterRows(item);item.selected=item.selected||new Set();
 const filters=[['ALL','All'],['PAID','Paid'],['PARTIAL','Partial'],['UNPAID','Unpaid'],['REVIEW','Review']].map(([v,l])=>`<button class="hero-btn secondary" aria-pressed="${(item.filter||'ALL')===v}" onclick="${mwOn('mwSetRoster',target,'filter',v)}">${l}</button>`).join('');
 const sortOptions=[['name','Name A–Z'],['balance','Largest outstanding'],['paid','Largest paid'],['memberId','Member ID']].map(([v,l])=>`<option value="${v}" ${(item.sort||'name')===v?'selected':''}>${l}</option>`).join('');
 el.innerHTML=`<h3 style="margin:24px 0 12px">${fpEscape(d.fund.code)} · Paid &amp; unpaid members</h3><div class="mw-review-stats"><div class="mw-review-stat"><span>Members · ${s.exempt} exempt</span><strong>${s.rows}</strong></div><div class="mw-review-stat"><span>Paid / credit-covered · unpaid</span><strong>${s.paid} / ${s.unpaid}</strong></div><div class="mw-review-stat mw-review-confirmed"><span>Recorded fund contributions</span><strong>${fpMoney(s.confirmedCash)}</strong></div></div><p>${s.review} records need review · ${fpMoney(s.outstanding)} verified outstanding</p><div class="fp-actions">${filters}</div><div class="fp-fields"><label>Search member <input data-roster="${fpEscape(target)}" aria-label="Search fund members" value="${fpEscape(item.query||'')}" onchange="mwSetRoster(this.dataset.roster,'query',this.value)" placeholder="Name or member ID"></label><label>Sort <select data-roster="${fpEscape(target)}" aria-label="Sort fund members" onchange="mwSetRoster(this.dataset.roster,'sort',this.value)">${sortOptions}</select></label></div><div class="fp-actions"><button class="hero-btn secondary" onclick="${mwOn('mwDownloadRoster',target)}">Export CSV</button><button class="hero-btn secondary" onclick="${mwOn('mwPrintRoster',target)}">Print / save PDF</button><button class="hero-btn primary" onclick="${mwOn('mwRosterReminders',target)}">Bulk reminder · selected members</button></div><p>${rows.length} matching · ${item.selected.size} selected</p>`+prTable(['Select','Member','Status','Paid','Credit applied','Outstanding','Payment dates','Issues'],rows.map(m=>[
 `<input type="checkbox" aria-label="Select ${fpEscape(m.name)}" ${item.selected.has(m.memberId)?'checked':''} ${m.formerMember?'disabled':''} onclick="${mwOn('mwToggleRoster',target,m.memberId)}">`,m.formerMember?fpEscape(m.name)+'<br><small>Former member</small>':prProfileButton(m.memberId,m.name),'<span class="mw-payment-status '+(m.status==='REVIEW'?'needs-review':'')+'">'+fpEscape(m.status)+'</span>',fpMoney(m.paid),fpMoney(m.creditApplied),m.balance===null?'Review':fpMoney(m.balance),(m.paymentDates||[]).map(fpEscape).join('<br>')||(m.creditApplied>0?'Covered by applied credit':'No recorded fund payment'),(m.issues||[]).map(fpEscape).join('<br>')]));
}
function mwDownloadRoster(target){const item=mwRosters[target];if(item)mwCSV(item.data.fund.code+'-members.csv',mwRosterExportRows(item));}
function mwPrintRoster(target){const item=mwRosters[target];if(item)mwPrint(item.data.fund.code+' · Paid & unpaid members',mwRosterExportRows(item));}
async function mwPaymentSuggestions(row){const el=document.getElementById('mw-payment-suggestions');if(!el)return;el.textContent='Checking memo hints…';try{const d=await fpCall('fp_admin_suggest',{sourceRow:row});if(!document.getElementById('mw-payment-suggestions'))return;el.innerHTML='<div class="fp-note"><strong>Memo hints · verify before using</strong><p>Exact member IDs: '+fpEscape(d.memberIds.join(', ')||'None found')+'<br>Possible IDs: '+fpEscape(d.possibleMemberIds.join(', ')||'None')+'<br>Fund references: '+fpEscape(d.fundCodes.join(', ')||'None found')+(d.creditMention?'<br>Memo mentions future payments or credit. Confirm the exact remaining amount.':'')+'</p>'+fpEscape(d.message)+'</div>';}catch(e){el.textContent=e.message;}}
const MW_ADMIN_UI=`<section class="card fp-panel" id="sec-admin-workflows"><div class="card-header"><span class="card-title">Guided administration</span></div><div class="fp-body"><p>Choose a task, check its requirements, preview the exact impact, then confirm. Nothing runs automatically from this screen.</p><label for="mw-admin-task">What do you need to do?</label><select id="mw-admin-task" onchange="mwAdminChange()"><option value="BALANCE_REMINDERS">Send selected members separate balance statements</option><option value="REMINDERS">Send consolidated payment reminders</option><option value="LATE_APPLY">Apply overdue late fees to selected members</option><option value="LATE_REVERSE">Reverse a verified unpaid late fee</option><option value="CLEANUP">Clean up already-removed members from pending fund lists</option><option value="REMOVE">Remove selected members after approved final-notice review</option><option value="BOARD_BADGES">Record confirmed Board member badges</option><option value="SLIDES">Prepare fund slides for a meeting</option><option value="OPEN_FUND">Open a verified funeral fund</option></select><div class="fp-note" id="mw-admin-help"></div><div id="mw-admin-members-wrap"><label for="mw-admin-members">Member IDs (comma separated, maximum 20)</label><input id="mw-admin-members" placeholder="MW0001, MW0200" oninput="mwAdminInvalidate()"></div><div id="mw-admin-fund-wrap"><label for="mw-admin-fund">Fundraiser</label><select id="mw-admin-fund" onchange="mwAdminInvalidate()"></select></div><div id="mw-admin-reason-wrap"><label for="mw-admin-reason">Reason for this correction</label><input id="mw-admin-reason" oninput="mwAdminInvalidate()"></div><div id="mw-admin-board-wrap"><label for="mw-admin-board">Board approval / case reference</label><input id="mw-admin-board" oninput="mwAdminInvalidate()"><label><input id="mw-admin-case" type="checkbox" onchange="mwAdminInvalidate()"> I confirm the required Board/Welfare verification, including the member’s opportunity to present their case for removal.</label></div><div id="mw-admin-open-wrap"><label for="mw-admin-deceased">Deceased’s declared full name</label><input id="mw-admin-deceased" oninput="mwAdminInvalidate()"><label for="mw-admin-relationship">Relationship</label><select id="mw-admin-relationship" onchange="mwAdminInvalidate()"><option>Father</option><option>Mother</option><option>Spouse</option><option>Child</option><option>Sibling</option><option>Self</option></select><label for="mw-admin-amount">Contribution per member</label><input id="mw-admin-amount" type="number" min="10" value="10" oninput="mwAdminInvalidate()"><label for="mw-admin-deadline">Contribution deadline</label><input id="mw-admin-deadline" type="date" onchange="mwAdminInvalidate()"><label for="mw-admin-evidence">Verification reference: declaration and payment confirmed before loss</label><input id="mw-admin-evidence" oninput="mwAdminInvalidate()"></div><div id="mw-admin-position-wrap"><label for="mw-admin-position">Board position</label><input id="mw-admin-position" value="Board Member" oninput="mwAdminInvalidate()"></div><div class="fp-actions"><button class="hero-btn secondary" onclick="mwAdminPreviewTask()">1. Dry run / preview</button><button id="mw-admin-confirm" disabled class="hero-btn primary" onclick="mwAdminConfirmTask()">2. Confirm this task</button></div><div id="mw-admin-status" role="status"></div><div id="mw-admin-preview"></div></div></section>`;
function mwAdminPrepare(){const sel=document.getElementById('mw-admin-fund');if(!sel)return;const current=sel.value;sel.replaceChildren(new Option('Select a fund',''));fpFundDetails.forEach(f=>sel.add(new Option(f.code+' — '+f.deceased,f.code)));sel.value=current;mwAdminChange();}
function mwAdminInvalidate(){mwAdminPreview=null;const b=document.getElementById('mw-admin-confirm');if(b)b.disabled=true;}
function mwAdminChange(){mwAdminInvalidate();const task=document.getElementById('mw-admin-task').value;const visibility={'members':!['CLEANUP','SLIDES'].includes(task),'fund':['LATE_APPLY','LATE_REVERSE'].includes(task),'reason':['LATE_APPLY','LATE_REVERSE'].includes(task),'board':['REMOVE','OPEN_FUND'].includes(task),'open':task==='OPEN_FUND','position':task==='BOARD_BADGES'};Object.entries(visibility).forEach(([name,show])=>document.getElementById('mw-admin-'+name+'-wrap').hidden=!show);const help={BALANCE_REMINDERS:'Preview each member’s separate balance statement, then confirm the selected emails. No balances change.',BOARD_BADGES:'Use only the confirmed Board roster. Display badges do not grant payment access or contribution exemptions.',REMINDERS:'One consolidated email per selected member, listing their outstanding funds. Review the full email first. Same-day logged reminders are held.',LATE_APPLY:'Only overdue, non-exempt balances with no fee already assessed can be charged. Preview lists the exact balances before and after.',LATE_REVERSE:'Only a verified unpaid $5 fee can be reversed. Paid fees need a separate refund/credit review.',CLEANUP:'For people already removed with a dated removal record and absent from MEMBERS. Paid or credit-covered historical TRACK rows are retained to protect fund totals.',REMOVE:'Requires a sent final notice, passed deadline, remaining notified arrears and recorded Board approval. This is not automatic removal based solely on a missed-fund count.',SLIDES:'Runs your existing fund-slides generator. It creates a Google Slides deck and sends its link to leadership.',OPEN_FUND:'Verify registration, declaration timing and Welfare/Board evidence. A previous/possible claim stops creation. Existing fund creation also applies stored credit; every effect is listed in the preview.'};document.getElementById('mw-admin-help').textContent=help[task];}
function mwAdminInput(){const value=id=>document.getElementById('mw-admin-'+id).value.trim();return {task:value('task'),requestId:mwAdminPreview?.input.requestId||crypto.randomUUID(),memberIds:value('members').toUpperCase().split(/[\s,;]+/).filter(Boolean),fundCode:value('fund'),reason:value('reason'),boardReference:value('board'),caseReviewed:document.getElementById('mw-admin-case').checked?'YES':'NO',deceased:value('deceased'),relationship:value('relationship'),deadline:value('deadline'),amount:value('amount'),evidence:value('evidence'),position:value('position')};}
async function mwAdminPreviewTask(){if(mwAdminBusy)return;mwAdminBusy=true;ftBusy=true;const el=document.getElementById('mw-admin-preview');mwAdminInvalidate();el.textContent='Checking current records and requirements…';try{const input=mwAdminInput(),d=await fpCall('fp_admin_preview',input);mwAdminPreview={input,token:d.previewToken};el.innerHTML='<div class="fp-note"><strong>'+fpEscape(d.summary)+'</strong><p>'+fpEscape(d.message)+'</p></div>'+mwAdminDetails(d.details);document.getElementById('mw-admin-confirm').disabled=false;}catch(e){el.textContent=mwServiceError(e.message);}finally{mwAdminBusy=false;ftBusy=false;}}
function mwAdminDetails(d){if(d.statements)return d.statements.map(m=>'<details><summary>'+fpEscape(m.memberId)+' · '+fpEscape(m.email)+'</summary><pre class="mw-email-preview">'+fpEscape(m.text)+'</pre></details>').join('');if(d.messages)return d.messages.map(m=>'<details><summary>'+fpEscape(m.group.id)+' · '+fpEscape(m.group.email)+' · '+fpMoney(m.group.totalDue)+'</summary><pre class="mw-email-preview">'+fpEscape(m.text)+'</pre></details>').join('');if(d.operations)return prTable(['Sheet','Row','Column','Before','After'],d.operations.map(o=>[fpEscape(o.sheet),String(o.row),String(o.col),fpEscape(JSON.stringify(o.before)),fpEscape(JSON.stringify(o.after))]));if(d.targets)return prTable(['Member','Fund tracker','Row','Action'],d.targets.map(t=>[fpEscape(t.memberId),fpEscape(t.sheet),String(t.row),'Archive then remove unpaid row']))+'<p>'+d.held.length+' paid/credit history rows retained.</p>';if(d.members)return prTable(['Member','Name','Notified arrears','Approval'],d.members.map(m=>[fpEscape(m.memberId),fpEscape(m.name),m.balance?fpMoney(m.balance.total):'Display badge only',fpEscape(d.boardReference||d.position||'')]));if(d.creditEffects)return prTable(['Member','Stored credit to be applied'],d.creditEffects.map(x=>[fpEscape(x.memberId),fpMoney(x.amount)]))+'<p>Deceased: '+fpEscape(d.deceased)+' · Claimant '+fpEscape(d.claimant)+' · Deadline '+fpEscape(d.deadline)+'</p>';if(d.funds)return '<ul>'+d.funds.map(f=>'<li>'+fpEscape(f.code+' — '+f.deceased)+'</li>').join('')+'</ul>';return '';}
async function mwAdminConfirmTask(){if(mwAdminBusy||!mwAdminPreview)return;const preview=mwAdminPreview,current=mwAdminInput();if(JSON.stringify(current)!==JSON.stringify(preview.input)){mwAdminInvalidate();return;}if(!confirm('Carry out only the task and effects shown in the dry run? This may change records or send the selected emails.'))return;mwAdminBusy=true;ftBusy=true;document.getElementById('mw-admin-confirm').disabled=true;const el=document.getElementById('mw-admin-status');el.textContent='Applying the confirmed task…';try{const d=await fpCall('fp_admin_apply',{...preview.input,previewToken:preview.token,confirmed:'YES'});el.textContent=d.message;document.getElementById('mw-admin-preview').textContent=JSON.stringify(d.result,null,2);mwAdminPreview=null;}catch(e){el.textContent=e.message+' Keep this request and inspect its audit before starting another.';}finally{mwAdminBusy=false;ftBusy=false;}}
async function prInspectSource(row){try{const d=await fpCall('fp_review_source',{sourceRow:row});if(!prFeed)prFeed={payments:[]};prFeed.payments=prFeed.payments.filter(x=>x.row!==row).concat(d.payment);prOpenPayment(row);}catch(e){prMessage(e.message,true);}}
async function mwRunInspection(offset=0){if(mwMailBusy)return;mwMailBusy=true;ftBusy=true;const el=document.getElementById('mw-mail-list'),status=document.getElementById('mw-mail-status');status.textContent='Inspecting individual bank messages against recorded rows…';try{const d=await fpCall('fp_admin_inspect',{period:document.getElementById('mw-mail-days').value,start:document.getElementById('mw-mail-start').value,end:document.getElementById('mw-mail-end').value,offset});el.innerHTML=(d.nextOffset===null?'':'<button class="hero-btn secondary" onclick="mwRunInspection('+d.nextOffset+')">Inspect next conversations</button>')+'<div class="mw-review-stats"><div class="mw-review-stat"><span>Recorded candidates</span><strong>'+d.stats.recorded+'</strong></div><div class="mw-review-stat"><span>Missing / review</span><strong>'+d.stats.missing+'</strong></div><div class="mw-review-stat"><span>Other review</span><strong>'+d.stats.review+'</strong></div></div>'+prTable(['Status / source','Memo','Finding','Actions'],d.items.map(m=>[fpEscape(m.auditStatus)+'<br>'+fpEscape(m.sender||'')+' '+(m.amount===undefined?'':fpMoney(m.amount)),fpEscape(m.memo||''),fpEscape(m.finding),'<a target="_blank" rel="noopener noreferrer" href="https://mail.google.com/mail/u/0/#all/'+encodeURIComponent(m.messageId)+'">Open bank email</a><br>'+(m.candidateRows||[]).map(r=>'<button class="hero-btn secondary" onclick="prInspectSource('+r.row+')">Inspect ledger row '+r.row+'</button>').join(' ')+(m.check?.canStage?'<button class="hero-btn secondary" onclick="mwMailStagePreview(\''+fpEscape(m.messageId)+'\')">Preview missing-source staging</button>':'') ]));status.textContent=d.message+(d.nextOffset===null?'':' More conversations remain; use the bank-email pages for the complete period.');}catch(e){status.textContent=e.message;}finally{mwMailBusy=false;ftBusy=false;}}
